use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str = "You are a customer-support agent. Answer the user's question \
using the supplied knowledge. If you need more facts, request the `lookup` tool with \
a focused query; otherwise reply with the final answer text.";

const MAX_ROUNDS: u32 = 8;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\n\nKnowledge:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut prompt = build_prompt(&ctx);
        let mut rounds: u32 = 0;

        loop {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > MAX_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration round limit exceeded".to_string(),
                        });
                    }
                    // The only tool in this node's scope is `lookup`, backed by the
                    // read-only knowledge-base handle. Anything else is out of scope.
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("requested tool not in scope: {}", req.tool),
                        });
                    }

                    let results = kb_read::lookup(&req.query);

                    prompt.push_str("\n\nTool `lookup` results for query \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\":\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }
    }
}

export!(Node);
```

